def icon(name):
 return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+ICONS[name]+'</svg>'

def external(url, text, cls=''):
 return f'<a href="{E(url)}" target="_blank" rel="noopener noreferrer" class="{E(cls)}">{text}</a>'

def header(active=''):
 links=[('work','/#work','Work'),('experience','/experience/','Experience'),('publications','/publications/','Publications'),('notes','/notes/','Notes'),('about','/about/','About')]
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==key else '')+f'>{label}</a>' for key,url,label in links)
 return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="container header-inner"><a href="/" class="brand" aria-label="Ming Chen home"><span class="brand-mark" aria-hidden="true">MC</span><span>Ming Chen<span class="period">.</span></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="primary-navigation" aria-label="Toggle navigation"><span></span><span></span></button><nav id="primary-navigation" class="nav-links" aria-label="Main navigation">{nav}<a href="/cv/" class="nav-cv"{' aria-current="page"' if active=='cv' else ''}>{icon('file')} CV</a></nav></div></header>'''

