def project_links(p):
 links=f'<a class="case-link" href="/projects/{p["id"]}/">Case study</a>'+external(p['paper'],icon('file')+('Preprint' if p['status']=='Preprint' else 'Paper'))
 if p.get('code'): links+=external(p['code'],icon('code')+'Code')
 return links

def project_card(p):
 return f'''<article class="project-card{' featured' if p['id']=='idynamics' else ''}" data-project-area="{p['area']}"><div class="project-art {p['id']}-art">{project_art(p['id'])}</div><div class="project-body"><div class="project-overline"><span>{E(p['tag'])}</span><span class="venue">{E(p['venue'])}</span></div><h3><a href="/projects/{p['id']}/">{E(p['name'])}</a></h3><p class="project-title">{E(p['title'])}</p><p class="project-summary">{E(p['summary'])}</p><ul class="tech-list" aria-label="Technologies">{''.join('<li>'+E(x)+'</li>' for x in p['technologies'])}</ul><div class="project-links">{project_links(p)}</div></div></article>'''

def citation(p):
 kind='inproceedings' if p['id']=='enbeats' else 'article'
 fields={'title':p['paper_title'],'author':p['authors'].replace(', and ', ', ').replace(' and ', ', ').replace(', ', ' and '),'year':p['year']}
 if p['id']=='idynamics':fields.update(journal='IEEE Transactions on Services Computing',doi='10.1109/TSC.2026.3735871',note='Early Access')
 elif p['id']=='trade':fields.update(journal='IEEE Transactions on Parallel and Distributed Systems',volume='37',number='1',pages='76--89',doi='10.1109/TPDS.2025.3626424')
 elif p['id']=='enbeats':fields.update(booktitle='2023 IEEE International Conference on Cloud Computing (CLOUD)',pages='144--154',doi='10.1109/CLOUD60044.2023.00025')
 else:fields.update(journal='arXiv preprint arXiv:'+p.get('arxiv','2607.15781'))
 fields['url']=p['paper']
 return '@'+kind+'{chen'+p['year']+p['id']+',\n'+',\n'.join('  '+k+' = {'+v+'}' for k,v in fields.items())+'\n}'

def publication(p, actions=True):
 authors=E(p['authors']).replace('Ming Chen','<strong>Ming Chen</strong>')
 extras='<br>Ming Chen: co-first and corresponding author.' if p['id']=='agentfair' else ''
 actions_html='<div class="pub-actions">'+external(p['paper'],'Preprint' if p['status']=='Preprint' else 'Paper')+(external(p['code'],'Code') if p.get('code') else '')+f'<button type="button" data-copy-citation="cite-{p["id"]}" aria-label="Copy BibTeX citation for {p["name"]}">Cite</button></div><pre class="sr-only" aria-hidden="true" id="cite-{p["id"]}">{E(citation(p))}</pre>' if actions else ''
 return f'''<article class="publication-item"><div class="publication-year">{p['year']}</div><div><h3><a href="{E(p['paper'])}" target="_blank" rel="noopener noreferrer">{E(p['paper_title'])}</a></h3><p class="publication-authors">{authors}{extras}</p><p class="publication-venue">{E(p['venue'])}{' · '+E(p['status']) if p['status'] not in p['venue'] else ''}</p></div>{actions_html}</article>'''

