 return layout(p['name'],p['summary'],f'''<main id="main"><section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/#work">Selected work</a><span>/</span><span>{p['name']}</span></div><div class="project-hero-grid"><div><div class="eyebrow">{E(p['tag'])}</div><h1>{p['name']}</h1><p class="lead">{E(p['summary'])}</p><div class="case-meta"><span>{E(p['venue'])}</span><span>·</span><span>{E(p['status'])}</span></div><div class="button-row">{resource_buttons}</div></div><div class="project-hero-art {p['id']}-art">{project_art(p['id'])}</div></div></div></section><section class="page-body"><div class="container case-body"><aside class="case-sidebar" aria-label="On this page"><span>On this page</span><a href="#problem">The problem</a><a href="#contribution">My contribution</a><a href="#decisions">Design decisions</a><a href="#evaluation">Evaluation</a><a href="#limitations">Limitations</a><a href="#resources">Paper & resources</a></aside><div class="prose"><h2 id="problem">The problem</h2><p>{E(p['problem'])}</p><h2 id="contribution">My contribution</h2><p>{E(p['contribution'])}</p><h2 id="decisions">Design decisions</h2>{decision_html}<h2 id="evaluation">Evaluation & outcomes</h2><p>{E(p['result'])}</p>{metric}{screenshot_html}<h2 id="limitations">What the results depend on</h2><p>{E(p['limitation'])}</p><h2 id="resources">Paper & resources</h2><p><strong>{E(p['paper_title'])}</strong></p><p>{E(p['authors'])}<br>{E(p['venue'])} · {E(p['status'])}</p><div class="button-row">{resource_buttons}</div><p class="source-note">This page summarizes the linked research and software. Diagrams on this website are explanatory illustrations; reported measurements come from the cited paper or project documentation.</p><div class="related-work"><a href="/#work">All projects</a><a href="/publications/">Publications</a></div></div></div></section></main>''','work')

