    return layout('Curriculum vitae','Ming Chen’s curriculum vitae: current wearable R&D, cloud and AI research, professional experience, industry supervision, publications, and teaching.',f'''<main id="main"><section class="page-hero"><div class="container cv-layout"><div class="cv-header"><div><div class="eyebrow">Curriculum vitae</div><h1>Ming Chen</h1><p class="lead">Researcher & engineer in cloud and AI systems</p><p style="font-size:14px;color:var(--muted);margin-top:15px">Melbourne, Australia · <a href="mailto:{DATA['email']}">{DATA['email']}</a></p></div><div class="button-row print-hide"><a class="button button-primary" href="/downloads/ming-chen-cv.pdf" download>Download PDF</a><button class="button" type="button" data-print>{icon('print')} Print / save PDF</button></div></div></div></section><section class="page-body"><div class="container cv-layout"><h2>Research profile</h2><p>{E(DATA['research_profile'])}</p><h2>Education</h2><h3>PhD · Engineering and IT (Computer Science) · The University of Melbourne</h3><p>March 2022–April 2026 · School of Computing and Information Systems<br>Thesis: <em>Demand Prediction and Service Scaling Methods for Microservices in Dynamic Computing Environments</em><br>Supervisor: Rajkumar Buyya; co-supervisors: Maria Rodriguez Read and Muhammed Tawfiqul Islam.</p><h3>BEng (Hons), Intelligence Science and Technology · Hunan University</h3><p>September 2012–June 2016 · Outstanding Undergraduate Thesis.</p><h2>Research & professional experience</h2>{experiences()}<h2>Selected publications & preprints</h2><div class="publication-list">{''.join(publication(p) for p in project_pubs)}</div><h2>Industry collaboration & supervision</h2><p>Supervised 10 partner-facing Master of Data Science projects involving approximately 50 postgraduate students. Responsibilities included problem formulation, method selection, technical review, evaluation, partner demonstrations, and handover.</p><ul>{partners}</ul><h2>Teaching</h2>{teaching_entries()}<h2>ML engineering</h2><h3>Reproducible Transformer training · Mainrun assessment study</h3><p>Implemented a modular training pipeline and completed 197 seven-epoch experiments with pinned inputs, configuration validation, evaluation-invariant checks, and CPU/CUDA numerical verification. Validation was reused during development.</p><h2>Technical skills</h2><p><strong>Programming:</strong> Python, Java, C/C++, MATLAB.<br><strong>Systems:</strong> Kubernetes, Docker, Linux, Istio, Prometheus, Grafana, cloud–edge computing, microservices, networking, ROS.<br><strong>AI & data:</strong> PyTorch, time-series forecasting, ensemble learning, anomaly prediction, RAG, LangGraph, FastAPI, SQLite, and LLM-agent workflows.<br><strong>Research practice:</strong> experimental design, reproducible benchmarking, numerical verification, technical writing, teaching, mentoring, and stakeholder communication.</p><h2>Selected recognition</h2><ul>{recognitions}</ul><h2>Profiles & contact</h2><p>{external(DATA['github'],'GitHub')} · {external(DATA['linkedin'],'LinkedIn')} · {external(DATA['scholar'],'Google Scholar')} · {external(DATA['orcid'],'ORCID')}<br><a href="mailto:{DATA['email']}">{DATA['email']}</a></p><p class="source-note">General web CV · Updated November 2026. The Publications page and Google Scholar provide the wider publication record.</p></div></section></main>''','cv',contact=False)


